private Evaluator evaluatorForAttribute(TokenQueue cq) {
    cq.consumeWhitespace();
    String key = consumeAttributeKey(cq);
    key = normalize(key);
    Validate.notEmpty(key);
    Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
    cq.consumeWhitespace();
    final Evaluator eval;

    if (cq.isEmpty()) {
        if (key.startsWith("^"))
            eval = new Evaluator.AttributeStarting(key.substring(1));
        else if (key.equals("*")) // any attribute
            eval = new Evaluator.AttributeStarting("");
        else
            eval = new Evaluator.Attribute(key);
    } else if (cq.matchChomp("~=")) { // keep regex semantics: remainder is the pattern
        eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder()));
    } else {
        final String op;
        if      (cq.matchChomp("!=")) op = "!=";
        else if (cq.matchChomp("^=")) op = "^=";
        else if (cq.matchChomp("$=")) op = "$=";
        else if (cq.matchChomp("*=")) op = "*=";
        else if (cq.matchChomp("="))  op = "=";
        else throw new Selector.SelectorParseException(
            "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());

        cq.consumeWhitespace();
        String value = consumeAttributeValue(cq); // raw token (quotes retained if quoted)
        boolean quoted = value.length() > 0 && (value.charAt(0) == '"' || value.charAt(0) == '\'');
        cq.consumeWhitespace();

        boolean caseSensitive = quoted; // CSS string values are case-sensitive by default; bare idents keep jsoup's legacy insensitive match
        if (!cq.isEmpty()) {
            char modifier = consumeModifier(cq); // i or s, else throws
            caseSensitive = modifier == 's';
            cq.consumeWhitespace();
            if (!cq.isEmpty())
                throw new Selector.SelectorParseException(
                    "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
        }

        switch (op) {
            case "=":  eval = new Evaluator.AttributeWithValue(key, value, caseSensitive); break;
            case "!=": eval = new Evaluator.AttributeWithValueNot(key, value, caseSensitive); break;
            ...
        }
    }
    return eval;
}
