private String consumeAttributeValue(TokenQueue cq) {
    if (cq.isEmpty()) return "";
    if (cq.matches('"') || cq.matches('\'')) {
        // quoted: raw token up to and including the closing quote (or to end if unterminated)
        StringBuilder sb = StringUtil.borrowBuilder();
        char quote = cq.consume();
        sb.append(quote);
        while (!cq.isEmpty()) {
            char c = cq.consume();
            sb.append(c);
            if (c == '\\' && !cq.isEmpty()) sb.append(cq.consume()); // keep escaped char with the escape
            else if (c == quote) break;
        }
        return StringUtil.releaseBuilder(sb);
    }
    // unquoted: up to the next whitespace
    StringBuilder sb = StringUtil.borrowBuilder();
    while (!cq.isEmpty() && !cq.matchesWhitespace()) sb.append(cq.consume());
    return StringUtil.releaseBuilder(sb);
}
