/**
 Consumes a CSS escape sequence (a backslash followed by a character, or up to 6 hexadecimal digits with an optional
 whitespace terminator) from the head of the queue, appending the decoded code point(s) to {@code out}.
 @param out the builder to append the decoded escape to
 @throws IllegalArgumentException if the escape sequence is incomplete (a backslash at the end of the input)
 */
public void consumeCssEscapeSequence(StringBuilder out) {
    advance(); // drop the backslash
    if (isEmpty()) throw new IllegalArgumentException("Invalid escape sequence: \\ at end of input");
    consumeCssEscapeSequenceInto(out);
}

/**
 Decodes CSS escape sequences (backslash escapes and hexadecimal code points) in the input string.
 @param in the string to decode
 @return the decoded string
 @throws IllegalArgumentException if an escape sequence is incomplete
 */
public static String unescapeCss(String in) {
    if (in.indexOf(Esc) == -1) return in;
    StringBuilder out = StringUtil.borrowBuilder();
    TokenQueue q = new TokenQueue(in);
    while (!q.isEmpty()) {
        if (q.matches(Esc)) q.consumeCssEscapeSequence(out);
        else out.append(q.consume());
    }
    q.close();
    return StringUtil.releaseBuilder(out);
}
```

