    final String value;
    final boolean caseSensitive;

    public AttributeKeyPair(String key, String value) {
        this(key, value, false);
    }

    AttributeKeyPair(String key, String value, boolean caseSensitive) {
        Validate.notEmpty(key);
        Validate.notNull(value);

        this.key = normalize(key);
        boolean quoted = value.startsWith("'") && value.endsWith("'")
            || value.startsWith("\"") && value.endsWith("\"");
        if (quoted) {
            Validate.isTrue(value.length() > 1, "Quoted value must have content");
            value = TokenQueue.unescapeCss(value.substring(1, value.length() - 1));
        }

        this.caseSensitive = caseSensitive;
        this.value = caseSensitive ? value : lowerCase(value); // case-insensitive match by default
    }

    /**
     @deprecated since 1.22.1, use {@link #AttributeKeyPair(String, String)}; the previous trimQuoted parameter is no longer used.
