import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class T {
    static Document doc = Jsoup.parse("<a id=a data-v=\"A B\"></a><a id=b data-v=\"a b\"></a><a id=c data-v=\"x&quot;y\"></a><a id=d data-v=\"\"></a><a id=f data-v=\"Alpha\"></a><i id=e></i>");
    static int failures = 0;

    static void check(String query, String... expectedIds) {
        Elements els = doc.select(query);
        StringBuilder actual = new StringBuilder();
        els.forEach(el -> actual.append(el.id()).append(','));
        StringBuilder expected = new StringBuilder();
        for (String id : expectedIds) expected.append(id).append(',');
        boolean ok = actual.toString().equals(expected.toString());
        if (!ok) failures++;
        System.out.printf("%-28s -> [%s] %s%n", query, actual, ok ? "OK" : ("FAIL expected [" + expected + "]"));
    }

    static void checkThrows(String query) {
        try {
            doc.select(query);
            failures++;
            System.out.printf("%-28s -> no exception FAIL%n", query);
        } catch (Selector.SelectorParseException e) {
            System.out.printf("%-28s -> throws: %s OK%n", query, e.getMessage());
        }
    }

    public static void main(String[] args) {
        check("[data-v=\"A B\"]", "a");
        check("[data-v=\"a b\" s]", "b");
        check("[data-v='x\\22 y']", "c");
        check("[data-v=\"\"]", "d");
        check("[data-v!=\"A B\"]", "b", "c", "d", "e", "f");
        check("[data-v^=alpha i]", "f");
        check("[data-v^=alpha s]");
        check("[\\64 ata-v=\"A B\"]", "a");
        check("[d\\61 ta-v=\"A B\"]", "a");
        check("[\\64 ata]", "a", "b", "c", "d", "f");
        check("[data-v]", "a", "b", "c", "d", "f");
        // case defaults
        check("[data-v=Alpha]", "f");       // unquoted default insensitive
        check("[data-v=\"Alpha\"]", "f");   // quoted default sensitive
        check("[data-v=\"alpha\"]");        // quoted sensitive: no match
        check("[data-v=\"alpha\" i]", "f"); // i modifier
        check("[data-v=\"Alpha\" s]", "f"); // s modifier
        check("[data-v=alpha]", "f");       // unquoted insensitive
        check("[data-v=alpha s]");          // unquoted + s -> sensitive
        check("[data-v*=LPH i]", "f");
        check("[data-v$=PHA i]", "f");
        check("[data-v$=PHA s]");
        check("[data-v!=\"\"]");            // complement of empty: a,b,c,e,f
        // whitespace around operators
        check("[ data-v = \"A B\" ]", "a");
        check("[data-v ~= B]");             // regex unchanged (" B" pattern w/ leading space)
        // errors
        checkThrows("[data-v=a b]");
        checkThrows("[data-v=\"a\" i i]");
        checkThrows("[data-v=\"a\" x]");
        checkThrows("[data-v=\"a\" i s]");
        checkThrows("[data-v i]");
        checkThrows("[data-v=\"a\"");
        checkThrows("[data-v='a]");
        checkThrows("[\"=\"]");
        checkThrows("[abs:!=]");
        System.out.println(failures == 0 ? "ALL OK" : failures + " FAILURES");
    }
}
EOF
