@Test void canSelectBlankAttribute() {
    Document doc = Jsoup.parse(
        "<div id=1 data=''></div>" +
            "<div id=2 data></div>" +
            "<div id=3 data=one></div>"
    );

    assertSelectedIds(doc.select("div[data]"), "1", "2", "3");
    assertSelectedIds(doc.select("div[data='']"), "1", "2");
    assertSelectedIds(doc.select("div[data=]"), "1", "2");

    assertSelectedIds(doc.select("div[data^='']"), "1", "2", "3");
    assertSelectedIds(doc.select("div[data$='']"), "1", "2", "3");
    assertSelectedIds(doc.select("div[data*='']"), "1", "2", "3");
}

