    static Document doc = Jsoup.parse("<a id=a data-v=\"A B\" data-eq=\"x=y\" data-q=\"x'y\" data-dq='x\"y'></a><a id=b data-v=\"a b\"></a><i id=e></i>");

    static void check(String query, String... expectedIds) {
        Elements els = doc.select(query);
        StringBuilder actual = new StringBuilder();
        els.forEach(el -> { if (!el.id().isEmpty()) actual.append(el.id()).append(','); });
        StringBuilder expected = new StringBuilder();
        for (String id : expectedIds) expected.append(id).append(',');
        boolean ok = actual.toString().equals(expected.toString());
        if (!ok) failures++;
        System.out.printf("%-30s -> ids[%s] %s%n", query, actual, ok ? "OK" : ("FAIL expected [" + expected + "]"));
    }

    static void checkThrows(String query) {
        try {
            doc.select(query);
            failures++;
            System.out.printf("%-30s -> no exception FAIL%n", query);
        } catch (Selector.SelectorParseException e) {
            System.out.printf("%-30s -> throws OK (%s)%n", query, e.getMessage());
        }
    }

    public static void main(String[] args) {
        check("[data-eq=\"x=y\"]", "a");          // equals inside quoted value
        check("[data-q=\"x'y\"]", "a");           // single quote inside double quotes
